function Field({label,children}:{label:string;children:ReactNode}){return <label className="site-control"><span>{label}</span>{children}</label>;}
const commitOnEnter=(e:ReactKeyboardEvent<HTMLInputElement>)=>{if(e.key==='Enter')e.currentTarget.blur();};
function TextInput({label,value,onCommit,placeholder,multiline,disabled}:{label:string;value:string;onCommit:(v:string)=>boolean|void;placeholder?:string;multiline?:boolean;disabled?:boolean}){const [draft,setDraft]=useState(value);useEffect(()=>setDraft(value),[value]);const commit=()=>{if(draft!==value&&onCommit(draft)===false)setDraft(value);};return <Field label={label}>{multiline?<textarea aria-label={label} rows={3} value={draft} placeholder={placeholder} disabled={disabled} onChange={e=>setDraft(e.target.value)} onBlur={commit}/>:<input aria-label={label} value={draft} placeholder={placeholder} disabled={disabled} onChange={e=>setDraft(e.target.value)} onBlur={commit} onKeyDown={commitOnEnter}/>}</Field>;}
function NumberInput({label,value,onCommit,placeholder,min,max,step}:{label:string;value:number|undefined;onCommit:(v:number|undefined)=>boolean|void;placeholder?:string;min?:number;max?:number;step?:number}){const text=value===undefined?'':String(value),[draft,setDraft]=useState(text);useEffect(()=>setDraft(text),[text]);const commit=()=>{if(draft===text)return;const parsed=draft.trim()===''?undefined:Number(draft);if(parsed!==undefined&&!Number.isFinite(parsed)||onCommit(parsed)===false)setDraft(text);};return <Field label={label}><input aria-label={label} type="number" value={draft} placeholder={placeholder} min={min} max={max} step={step??'any'} onChange={e=>setDraft(e.target.value)} onBlur={commit} onKeyDown={commitOnEnter}/></Field>;}
