const readDataUrl=(file:File)=>new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(Error('This file could not be read.'));reader.readAsDataURL(file);});
const decoded=(url:string)=>new Promise<void>((resolve,reject)=>{const image=new Image();image.onload=()=>image.naturalWidth?resolve():reject(Error('This image could not be decoded.'));image.onerror=()=>reject(Error('This image could not be decoded.'));image.src=url;});
/** Declared type, signature and an actual browser decode must all agree before an image enters the document. */
async function pickedImage(file:File,types?:string[],max?:number){if(file.size>(max??SITE_LIMITS.image))throw Error('This image is too large.');const url=await readDataUrl(file);if(!validSiteImage(url,max,types))throw Error('Choose a valid image in a supported format.');await decoded(url);return url;}
